  //----
  sessions hrm_platform_member_sessions[]
  passwordResets hrm_platform_member_password_resets[]
  ownedOrganizations hrm_platform_organizations[]
  employees hrm_platform_employees[]
  employeeDepartmentChanges hrm_platform_employee_department_histories[]
  taskHistories hrm_platform_task_histories[]
  reviewedTimesheets hrm_platform_timesheets[]
  activityLogs hrm_platform_activity_logs[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
