  /// JWT access token for API authentication.
  access_token String

  /// JWT refresh token for token renewal without re-authentication.
  refresh_token String

  /// IP address of the client connection.
  ip String

  /// Current page URL when session was created.
  href String

  /// Referrer URL from the client request.
  referrer String

  /// Session creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Session expiration timestamp for security enforcement.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member hrm_platform_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

