import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test guest registration with a new device fingerprint.
 *
 * This test verifies the primary success path for guest registration when a
 * unique device fingerprint is encountered for the first time. It validates
 * that a new guest account is created, session tokens are issued, and all
 * metadata is properly captured.
 */
export async function test_api_guest_join_new_device_registration(
  connection: api.IConnection,
): Promise<void> {
  // 1. Generate unique device fingerprint and session metadata
  const deviceFingerprint = RandomGenerator.alphaNumeric(32);
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();
  const ip = typia.random<string & tags.Format<"ipv4">>();
  // 2. Create guest-specific connection and register guest
  const guestConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_guest_join(guestConnection, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: href,
      referrer: referrer,
      ip: ip,
    } satisfies IHrmPlatformGuest.IJoin,
  });
  // 3. Validate response structure with typia
  typia.assert(authorized);
  // 4. Verify guest account details
  TestValidator.equals(
    "device fingerprint matches input",
    authorized.device_fingerprint,
    deviceFingerprint,
  );
  TestValidator.predicate(
    "created_at timestamp is set",
    authorized.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at timestamp is set",
    authorized.updated_at.length > 0,
  );
  TestValidator.equals(
    "deleted_at is null for new account",
    authorized.deleted_at,
    null,
  );
  // 5. Verify authorization token structure
  TestValidator.predicate(
    "access token is non-empty string",
    authorized.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token is non-empty string",
    authorized.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "expired_at timestamp is set",
    authorized.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refreshable_until timestamp is set",
    authorized.token.refreshable_until.length > 0,
  );
  // 6. Verify session records exist
  TestValidator.predicate(
    "at least one session created",
    authorized.sessions.length >= 1,
  );
  // 7. Validate first session details
  const session = authorized.sessions[0];
  if (session !== undefined) {
    TestValidator.equals(
      "session guest_id matches guest id",
      session.guest_id,
      authorized.id,
    );
    TestValidator.equals("session href matches input", session.href, href);
    TestValidator.equals(
      "session referrer matches input",
      session.referrer,
      referrer,
    );
    TestValidator.equals("session ip matches input", session.ip, ip);
    TestValidator.predicate(
      "session created_at is set",
      session.created_at.length > 0,
    );
    TestValidator.predicate(
      "session expired_at is set",
      session.expired_at.length > 0,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmPlatformGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformGuest";
import type { IHrmPlatformGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformGuestSession";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test returning guest recognition by device fingerprint.
 *
 * This test verifies that when a guest with an existing device fingerprint
 * attempts to join again, the system recognizes them as the same guest
 * and issues new session tokens without creating a duplicate account.
 *
 * Test Steps:
 * 1. Register a new guest with a unique device fingerprint
 * 2. Store the guest ID and initial session count
 * 3. Call join again with the same device fingerprint but different metadata
 * 4. Verify same guest ID is returned with new tokens
 * 5. Verify session count increased by 1
 */
export async function test_api_guest_join_returning_device_recognition(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: First registration - create a new guest
  const guestConnection1: api.IConnection = { host: connection.host };
  const deviceFingerprint = RandomGenerator.alphaNumeric(32);
  const firstHref = typia.random<string & tags.Format<"uri">>();
  const firstReferrer = typia.random<string & tags.Format<"uri">>();
  const firstIp = typia.random<string & tags.Format<"ipv4">>();
  const firstJoin = await authorize_guest_join(guestConnection1, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: firstHref,
      referrer: firstReferrer,
      ip: firstIp,
    } satisfies IHrmPlatformGuest.IJoin,
  });
  typia.assert(firstJoin);
  // Store initial guest data
  const guestId = firstJoin.id;
  const firstSessionCount = firstJoin.sessions.length;
  const firstAccessToken = firstJoin.token.access;
  const firstCreatedAt = firstJoin.created_at;
  const firstUpdatedAt = firstJoin.updated_at;
  // Step 2: Wait briefly to ensure timestamp difference
  await new Promise((resolve) => setTimeout(resolve, 100));
  // Step 3: Second join with same device fingerprint but different metadata
  const guestConnection2: api.IConnection = { host: connection.host };
  const secondHref = typia.random<string & tags.Format<"uri">>();
  const secondReferrer = typia.random<string & tags.Format<"uri">>();
  const secondIp = typia.random<string & tags.Format<"ipv4">>();
  const secondJoin = await authorize_guest_join(guestConnection2, {
    body: {
      device_fingerprint: deviceFingerprint,
      href: secondHref,
      referrer: secondReferrer,
      ip: secondIp,
    } satisfies IHrmPlatformGuest.IJoin,
  });
  typia.assert(secondJoin);
  // Step 4: Verify same guest ID is returned (no duplicate created)
  TestValidator.equals("guest ID matches", secondJoin.id, guestId);
  // Step 5: Verify new tokens are issued (different from first)
  TestValidator.notEquals(
    "access token refreshed",
    secondJoin.token.access,
    firstAccessToken,
  );
  TestValidator.notEquals(
    "refresh token refreshed",
    secondJoin.token.refresh,
    firstJoin.token.refresh,
  );
  // Step 6: Verify session count increased by 1
  TestValidator.equals(
    "session count increased",
    secondJoin.sessions.length,
    firstSessionCount + 1,
  );
  // Step 7: Verify guest updated_at timestamp changed
  TestValidator.notEquals(
    "guest updated_at changed",
    secondJoin.updated_at,
    firstUpdatedAt,
  );
  // Step 8: Verify the new session has the new metadata
  const newSession = secondJoin.sessions[secondJoin.sessions.length - 1];
  typia.assertGuard(newSession!);
  TestValidator.equals("new session href", newSession.href, secondHref);
  TestValidator.equals(
    "new session referrer",
    newSession.referrer,
    secondReferrer,
  );
  TestValidator.equals("new session ip", newSession.ip, secondIp);
  // Step 9: Verify created_at remains the same (same guest account)
  TestValidator.equals(
    "guest created_at unchanged",
    secondJoin.created_at,
    firstCreatedAt,
  );
  // Step 10: Verify deleted_at is still null
  TestValidator.equals("guest not deleted", secondJoin.deleted_at, null);
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmPlatformGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformGuest";
import type { IHrmPlatformGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmPlatformGuestSession";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test guest session token refresh functionality.
 *
 * This test validates the complete guest session refresh workflow:
 * 1. Create initial guest session via join endpoint
 * 2. Extract refresh_token from join response
 * 3. Call refresh endpoint with valid refresh_token
 * 4. Verify token rotation (new access and refresh tokens)
 * 5. Validate guest ID remains consistent
 * 6. Confirm session expiration is extended
 */
export async function test_api_guest_refresh_session_token(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create initial guest session to obtain refresh token
  const guestJoin = await authorize_guest_join(connection, {
    body: {
      device_fingerprint: RandomGenerator.alphaNumeric(32),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IHrmPlatformGuest.IJoin,
  });
  typia.assert(guestJoin);
  // 2. Extract tokens and guest information from initial join
  const originalRefreshToken = guestJoin.token.refresh;
  const originalAccessToken = guestJoin.token.access;
  const guestId = guestJoin.id;
  const originalExpiredAt = guestJoin.token.expired_at;
  const originalRefreshableUntil = guestJoin.token.refreshable_until;
  // 3. Refresh the session using the refresh token
  const refreshedGuest = await authorize_guest_refresh(connection, {
    body: {
      refresh_token: originalRefreshToken,
    } satisfies IHrmPlatformGuest.IRefresh,
  });
  typia.assert(refreshedGuest);
  // 4. Validate guest ID remains the same
  TestValidator.equals("guest ID matches", refreshedGuest.id, guestId);
  TestValidator.equals(
    "device fingerprint matches",
    refreshedGuest.device_fingerprint,
    guestJoin.device_fingerprint,
  );
  // 5. Validate token rotation (new tokens must be different)
  TestValidator.notEquals(
    "access token rotated",
    refreshedGuest.token.access,
    originalAccessToken,
  );
  TestValidator.notEquals(
    "refresh token rotated",
    refreshedGuest.token.refresh,
    originalRefreshToken,
  );
  // 6. Validate session expiration is extended
  TestValidator.predicate(
    "expired_at extended",
    new Date(refreshedGuest.token.expired_at) > new Date(originalExpiredAt),
  );
  TestValidator.predicate(
    "refreshable_until extended",
    new Date(refreshedGuest.token.refreshable_until) >
      new Date(originalRefreshableUntil),
  );
  // 7. Validate token format and structure
  TestValidator.predicate(
    "access token is non-empty",
    refreshedGuest.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token is non-empty",
    refreshedGuest.token.refresh.length > 0,
  );
}

