    "session A expired_at is in the future",
    () => new Date(sessionAToken.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "session B expired_at is in the future",
    () => new Date(sessionBToken.expired_at) > new Date(),
  );
}

