/**
 * Test that a user with employee:view permission can successfully retrieve
 * another employee's contract details. The test should: (1) Create a manager
 * member account with a role that has employee:view permission (such as Owner
 * or Manager built-in role), (2) Join as the manager, (3) Create an employee
 * record for a different user, (4) Create an employment contract for that
 * employee, (5) Retrieve the contract using the GET endpoint with the manager's
 * credentials. Verify the response contains complete contract information
 * including all employment terms. This validates the permission-based access
 * control where users with employee:view or employee:manage permission can
 * access any employee's contracts within their organization for administrative
 * purposes.
 */
export async function test_api_employee_contract_view_by_manager(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create manager account with employee:view permission
  const managerConnection: api.IConnection = { host: connection.host };
  const manager = await authorize_member_join(managerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "ManagerPass123!",
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(manager);
  // 2. Create employee member account (different user)
  const employeeMemberConnection: api.IConnection = { host: connection.host };
  const employeeMember = await authorize_member_join(employeeMemberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "EmployeePass123!",
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(employeeMember);
  // 3. Create employee record for the employee member (using manager connection)
  // The generate function handles required fields like role_id internally
  const employee = await generate_random_hrm_platform_member_employees_create(
    managerConnection,
    {
      body: {
        member_id: employeeMember.id,
        employment_type: "full-time",
      } as DeepPartial<IHrmPlatformEmployee.ICreate>,
    },
  );
  typia.assert(employee);
  // 4. Create employment contract for the employee
  const contract =
    await generate_random_hrm_platform_member_employees_contracts_create(
      managerConnection,
      {
        params: { employeeId: employee.id },
        body: {
          start_date: new Date().toISOString(),
          pay_rate: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          pay_period: RandomGenerator.pick([
            "hourly",
            "daily",
            "weekly",
            "monthly",
          ] as const),
          working_hours_per_week: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<20> & tags.Maximum<60>
          >(),
        } as DeepPartial<IHrmPlatformEmployeeContract.ICreate>,
      },
    );
  typia.assert(contract);
  // 5. Retrieve the contract using manager's credentials (employee:view permission)
  const retrievedContract =
    await api.functional.hrmPlatform.member.employees.contracts.at(
      managerConnection,
      {
        employeeId: employee.id,
        contractId: contract.id,
      },
    );
  typia.assert(retrievedContract);
  // 6. Validate the retrieved contract contains complete information
  TestValidator.equals(
    "contract ID matches",
    retrievedContract.id,
    contract.id,
  );
  TestValidator.equals(
    "employee ID matches",
    retrievedContract.employee.id,
    employee.id,
  );
  TestValidator.equals(
    "start date matches",
    retrievedContract.start_date,
    contract.start_date,
  );
  TestValidator.equals(
    "pay rate matches",
    retrievedContract.pay_rate,
    contract.pay_rate,
  );
  TestValidator.equals(
    "pay period matches",
    retrievedContract.pay_period,
    contract.pay_period,
  );
  TestValidator.equals(
    "working hours matches",
    retrievedContract.working_hours_per_week,
    contract.working_hours_per_week,
  );
}

