export async function test_api_timelog_creation_for_assigned_project(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as a new member
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IHrmPlatformMember.IJoin,
  });
  typia.assert(authorized);
  // 2. Create employee record for the authenticated member
  const role_id = typia.random<string & tags.Format<"uuid">>();
  const employee = await generate_random_hrm_platform_member_employees_create(
    memberConnection,
    {
      body: {
        member_id: authorized.member.id,
        employment_type: "full-time",
        role_id,
      } satisfies IHrmPlatformEmployee.ICreate,
    },
  );
  typia.assert(employee);
  // 3. Create an active project
  const project = await generate_random_hrm_platform_member_projects_create(
    memberConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        color_code: "#3498db",
        status: "active",
      } satisfies IHrmPlatformProject.ICreate,
    },
  );
  typia.assert(project);
  // 4. Assign the employee to the project as a member
  const projectMember =
    await generate_random_hrm_platform_member_projects_members_create(
      memberConnection,
      {
        params: {
          projectId: project.id,
        },
        body: {
          hrm_platform_employee_id: employee.id,
          role: "member",
        } satisfies IHrmPlatformProjectMember.ICreate,
      },
    );
  typia.assert(projectMember);
  // 5. Create a timelog for the assigned project (no task_id)
  const today = new Date().toISOString();
  const timelog = await generate_random_hrm_platform_member_timelogs_create(
    memberConnection,
    {
      body: {
        project_id: project.id,
        date: today,
        duration_minutes: 60,
        billable: true,
        description: RandomGenerator.paragraph({ sentences: 1 }),
      } satisfies IHrmPlatformTimelog.ICreate,
    },
  );
  typia.assert(timelog);
  // Validate timelog response
  TestValidator.equals("employee matches", timelog.employee.id, employee.id);
  TestValidator.equals("project matches", timelog.project.id, project.id);
  TestValidator.equals("task is null", timelog.task, null);
  TestValidator.equals("billable is true", timelog.billable, true);
  TestValidator.equals("duration matches", timelog.duration_minutes, 60);
  TestValidator.predicate("has valid id", timelog.id !== null);
  TestValidator.predicate("has created_at", timelog.created_at !== null);
  TestValidator.predicate("has updated_at", timelog.updated_at !== null);
  // Validate timesheet association (null if no draft exists, or draft timesheet if exists)
  if (timelog.timesheet !== null) {
    typia.assert(timelog.timesheet);
    TestValidator.predicate("timesheet has id", timelog.timesheet.id !== null);
  }
}

