export async function test_api_timesheet_retrieve_own_by_employee(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register new member and authenticate
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IHrmPlatformMember.IJoin,
  });
  typia.assert(authorized);
  // 2. Create employee record for the authenticated member
  const employee = await generate_random_hrm_platform_member_employees_create(
    memberConnection,
    {
      body: {
        member_id: authorized.id,
        employment_type: "full-time",
      },
    },
  );
  typia.assert(employee);
  // 3. Create a project
  const project = await generate_random_hrm_platform_member_projects_create(
    memberConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        color_code: "#3498db",
      },
    },
  );
  typia.assert(project);
  // 4. Assign employee to the project as a member
  const projectMember =
    await generate_random_hrm_platform_member_projects_members_create(
      memberConnection,
      {
        params: { projectId: project.id },
        body: {
          hrm_platform_employee_id: employee.id,
          role: "member",
        },
      },
    );
  typia.assert(projectMember);
  // 5. Create a timelog entry for the employee on that project
  const timelog = await generate_random_hrm_platform_member_timelogs_create(
    memberConnection,
    {
      body: {
        project_id: project.id,
        date: new Date().toISOString(),
        duration_minutes: 120,
        description: "Test work description",
        billable: true,
      },
    },
  );
  typia.assert(timelog);
  // 6. Create a draft timesheet for the current week
  const monday = new Date();
  monday.setDate(monday.getDate() - (monday.getDay() || 7) + 1);
  monday.setHours(0, 0, 0, 0);
  const timesheet = await generate_random_hrm_platform_member_timesheets_create(
    memberConnection,
    {
      body: {
        week_start_date: monday.toISOString(),
      },
    },
  );
  typia.assert(timesheet);
  // 7. Retrieve the timesheet using GET /hrmPlatform/member/timesheets/{timesheetId}
  const retrievedTimesheet =
    await api.functional.hrmPlatform.member.timesheets.at(memberConnection, {
      timesheetId: timesheet.id,
    });
  typia.assert(retrievedTimesheet);
  // 8. Validate the response
  TestValidator.equals(
    "timesheet ID matches",
    retrievedTimesheet.id,
    timesheet.id,
  );
  TestValidator.equals("status is draft", retrievedTimesheet.status, "draft");
  TestValidator.equals(
    "employee ID matches",
    retrievedTimesheet.employee.id,
    employee.id,
  );
  TestValidator.equals(
    "week start date matches",
    retrievedTimesheet.week_start_date,
    timesheet.week_start_date,
  );
  TestValidator.equals(
    "week end date matches",
    retrievedTimesheet.week_end_date,
    timesheet.week_end_date,
  );
  TestValidator.predicate(
    "has timelogs array",
    Array.isArray(retrievedTimesheet.timelogs),
  );
  TestValidator.predicate(
    "timelogs array is not empty",
    retrievedTimesheet.timelogs.length > 0,
  );
  const foundTimelog = retrievedTimesheet.timelogs.find(
    (t) => t.id === timelog.id,
  );
  TestValidator.predicate(
    "timelog exists in timesheet",
    foundTimelog !== undefined,
  );
  if (foundTimelog) {
    TestValidator.equals(
      "timelog project matches",
      foundTimelog.project.id,
      project.id,
    );
    TestValidator.equals(
      "timelog duration matches",
      foundTimelog.duration_minutes,
      120,
    );
    TestValidator.equals(
      "timelog billable matches",
      foundTimelog.billable,
      true,
    );
  }
}

