  TestValidator.equals("project matches", timer.project.id, project.id);
  TestValidator.equals("employee matches", timer.employee.id, employee.id);
  TestValidator.predicate("started_at is set", timer.started_at !== null);
  TestValidator.equals("stopped_at is null", timer.stopped_at, null);
  TestValidator.equals("task is null", timer.task, null);
  TestValidator.predicate("created_at is set", timer.created_at !== null);
  TestValidator.predicate("updated_at is set", timer.updated_at !== null);
}

