export async function putHrmPlatformMemberProjectsProjectIdTasksTaskId(props: {
  member: MemberPayload;
  projectId: string & tags.Format<"uuid">;
  taskId: string & tags.Format<"uuid">;
  body: IHrmPlatformTask.IUpdate;
}): Promise<IHrmPlatformTask> {
  // Verify task exists and belongs to the specified project
  const task = await MyGlobal.prisma.hrm_platform_tasks.findUniqueOrThrow({
    where: { id: props.taskId },
    select: {
      id: true,
      hrm_platform_project_id: true,
      status: true,
      hrm_platform_employee_id: true,
      parent_id: true,
    },
  });
  if (task.hrm_platform_project_id !== props.projectId) {
    throw new HttpException(
      "Task does not belong to the specified project",
      400,
    );
  }
  // Get employee record for the authenticated member to check project membership and role
  const employee = await MyGlobal.prisma.hrm_platform_employees.findFirst({
    where: {
      member_id: props.member.id,
      deleted_at: null,
    },
    select: {
      id: true,
      role_id: true,
    },
  });
  if (!employee) {
    throw new HttpException("Employee record not found", 403);
  }
  // Check authorization: project-lead role in project_members OR project:manage permission via role
  const projectMembership =
    await MyGlobal.prisma.hrm_platform_project_members.findFirst({
      where: {
        hrm_platform_project_id: props.projectId,
        hrm_platform_employee_id: employee.id,
        deleted_at: null,
      },
      select: {
        role: true,
      },
    });
  let isAuthorized = false;
  // Check if project-lead in this project
  if (projectMembership && projectMembership.role === "project-lead") {
    isAuthorized = true;
  }
  // Check if has project:manage permission through organizational role
  if (!isAuthorized) {
    const rolePermissions =
      await MyGlobal.prisma.hrm_platform_role_permissions.findFirst({
        where: {
          role_id: employee.role_id,
          permission: "project:manage",
        },
      });
    if (rolePermissions) {
      isAuthorized = true;
    }
  }
  if (!isAuthorized) {
    throw new HttpException(
      "Forbidden: insufficient permissions to update this task",
      403,
    );
  }
  // Validate assigned employee (if provided) is a member of the project
  if (props.body.hrm_platform_employee_id !== undefined) {
    if (props.body.hrm_platform_employee_id === null) {
      // Unassigning is allowed
    } else {
      const assigneeMembership =
        await MyGlobal.prisma.hrm_platform_project_members.findFirst({
          where: {
            hrm_platform_project_id: props.projectId,
            hrm_platform_employee_id: props.body.hrm_platform_employee_id,
            deleted_at: null,
          },
        });
      if (!assigneeMembership) {
        throw new HttpException(
          "Assigned employee must be a member of the project",
          400,
        );
      }
    }
  }
  // Validate parent task (if provided) belongs to same project and is not a subtask
  if (props.body.parent_id !== undefined) {
    if (props.body.parent_id === null) {
      // Removing parent is allowed
    } else {
      const parentTask =
        await MyGlobal.prisma.hrm_platform_tasks.findUniqueOrThrow({
          where: { id: props.body.parent_id },
          select: {
            hrm_platform_project_id: true,
            parent_id: true,
          },
        });
      if (parentTask.hrm_platform_project_id !== props.projectId) {
        throw new HttpException(
          "Parent task must belong to the same project",
          400,
        );
      }
      if (parentTask.parent_id !== null) {
        throw new HttpException(
          "Parent task cannot be a subtask (one-level nesting only)",
          400,
        );
      }
    }
  }
  // Create task history record if status is changing
  if (props.body.status !== undefined && props.body.status !== task.status) {
    await MyGlobal.prisma.hrm_platform_task_histories.create({
      data: {
        id: v4(),
        task_id: props.taskId,
        user_id: props.member.id,
        old_status: task.status,
        new_status: props.body.status,
        created_at: new Date(),
      },
    });
  }
  // Build update data object with only provided fields
  const updateData: Prisma.hrm_platform_tasksUpdateInput = {
    updated_at: new Date(),
    ...(props.body.title !== undefined && { title: props.body.title }),
    ...(props.body.description !== undefined && {
      description: props.body.description,
    }),
    ...(props.body.status !== undefined && { status: props.body.status }),
    ...(props.body.priority !== undefined && { priority: props.body.priority }),
    ...(props.body.estimated_hours !== undefined && {
      estimated_hours: props.body.estimated_hours,
    }),
    ...(props.body.due_date !== undefined && {
      due_date: props.body.due_date ? new Date(props.body.due_date) : null,
    }),
    ...(props.body.hrm_platform_employee_id !== undefined && {
      assignee:
        props.body.hrm_platform_employee_id === null
          ? { disconnect: true }
          : { connect: { id: props.body.hrm_platform_employee_id } },
    }),
    ...(props.body.parent_id !== undefined && {
      parent:
        props.body.parent_id === null
          ? { disconnect: true }
          : { connect: { id: props.body.parent_id } },
    }),
  };
  // Update the task
  await MyGlobal.prisma.hrm_platform_tasks.update({
    where: { id: props.taskId },
    data: updateData,
  });
  // Fetch and return the updated task
  const updated = await MyGlobal.prisma.hrm_platform_tasks.findUniqueOrThrow({
    where: { id: props.taskId },
    ...HrmPlatformTaskTransformer.select(),
  });
  return await HrmPlatformTaskTransformer.transform(updated);
}

