import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IHrmPlatformGuest } from "../../../../api/structures/IHrmPlatformGuest";
import { postHrmPlatformAuthGuestJoin } from "../../../../providers/postHrmPlatformAuthGuestJoin";
import { postHrmPlatformAuthGuestRefresh } from "../../../../providers/postHrmPlatformAuthGuestRefresh";

@Controller("/hrmPlatform/auth/guest")
export class HrmplatformAuthGuestController {
  /**
   * Register a new guest account or recognize returning guest by device fingerprint.
   *
   * This endpoint creates a new guest account in the hrm_platform_guests table when a device fingerprint is encountered for the first time. The device_fingerprint field serves as the unique identifier for guest recognition across sessions, enabling continuity without requiring email/password authentication.
   *
   * For returning guests with an existing device_fingerprint, the operation recognizes the guest and issues new session tokens without creating a duplicate account. This supports the temporary, frictionless access model for unauthenticated platform visitors.
   *
   * Upon successful guest registration or recognition, a new session record is created in hrm_platform_guest_sessions with access_token, refresh_token, and connection metadata (ip, href, referrer). The session includes an expired_at timestamp for automatic invalidation.
   *
   * The response contains the guest's authorized tokens (access and refresh) along with guest identification, enabling immediate platform access for temporary visitors.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Device fingerprint for guest identification and recognition.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Create a new guest account using device fingerprint identification. The service generates a unique guest ID and stores the device_fingerprint for future recognition. A new guest session is created with access and refresh tokens, connection metadata (IP, href, referrer), and expiration timestamp. The device_fingerprint must be unique - if a guest with the same fingerprint exists, return the existing guest's tokens instead of creating a duplicate. Tokens are JWT-based with appropriate expiration times for temporary guest access.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IHrmPlatformGuest.IJoin,
  ): Promise<IHrmPlatformGuest.IAuthorized> {
    try {
      return await postHrmPlatformAuthGuestJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Refresh guest session tokens to extend platform access.
   *
   * This endpoint enables guests to renew their authentication tokens without re-submitting their device fingerprint. The operation validates the provided refresh_token against the hrm_platform_guest_sessions table, ensuring the session exists and has not expired based on the expired_at timestamp.
   *
   * Upon successful validation, new JWT access and refresh tokens are generated and the session record is updated with the new tokens and extended expiration time. This maintains the guest's temporary access continuity while enforcing security through token rotation.
   *
   * If the refresh token is invalid, expired, or not found, the operation fails and the guest must re-authenticate through the join endpoint. This ensures that expired or compromised sessions cannot be renewed.
   *
   * The response returns fresh tokens (access and refresh) along with updated session expiration information, allowing the guest client to maintain seamless platform access.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for session renewal.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Refresh guest session tokens using the provided refresh token. The service validates the refresh token against hrm_platform_guest_sessions, checks expiration, and generates new access and refresh tokens. The existing session is updated with new tokens and extended expiration. Invalid or expired refresh tokens result in authentication failure, requiring the guest to re-join via the join endpoint.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IHrmPlatformGuest.IRefresh,
  ): Promise<IHrmPlatformGuest.IAuthorized> {
    try {
      return await postHrmPlatformAuthGuestRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

